import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';

import { AssociationNavbarComponent } from '../../shared/association-navbar.component';
import { AuthService } from '../../auth/auth.service';

interface RequestCard {
  id: number;
  title: string;
  description: string;
  organization: string;
  location: string;
  category: string;
  urgency: 'low' | 'medium' | 'high';
  progress: number;
  target: number;
  image?: string;
}

@Component({
  selector: 'app-association-explorer',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink, AssociationNavbarComponent],
  templateUrl: './association-explorer.component.html',
  styleUrl: './association-explorer.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AssociationExplorerComponent {
  private readonly router = inject(Router);
  private readonly auth = inject(AuthService);

  readonly isAssociation = signal(false);
  readonly searchQuery = signal('');
  readonly selectedCategory = signal('');
  readonly selectedLocation = signal('');
  readonly selectedUrgency = signal('');
  readonly sortBy = signal<'recent' | 'most-funded' | 'most-urgent'>('recent');

  readonly categories = ['Alimentation', 'Santé', 'Éducation', 'Logement', 'Emploi', 'Bien-être'];
  readonly locations = ['Tunis', 'Sfax', 'Sousse', 'Ariana', 'Ben Arous', 'Manouba'];
  readonly urgencies = ['Basse', 'Moyenne', 'Haute'];

  readonly allRequests = signal<RequestCard[]>([
    {
      id: 1,
      title: "Aide alimentaire d'urgence",
      description: "Soutien pour les familles en situation de crise alimentaire.",
      organization: 'Solidarité Plus',
      location: 'Tunis',
      category: 'Alimentation',
      urgency: 'high',
      progress: 850,
      target: 1200,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 2,
      title: 'Scolarité pour enfants défavorisés',
      description: 'Fournitures scolaires et tutorat pour enfants en besoin.',
      organization: 'Éducation pour Tous',
      location: 'Sfax',
      category: 'Éducation',
      urgency: 'medium',
      progress: 2340,
      target: 3000,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 3,
      title: 'Aide médicale urgente',
      description: 'Couverture de soins pour personnes sans ressources.',
      organization: 'Santé Solidaire',
      location: 'Sousse',
      category: 'Santé',
      urgency: 'high',
      progress: 1500,
      target: 2500,
      image: '/assets/images/placeholders/request-placeholder.svg'
    }
  ]);

  readonly filteredRequests = computed(() => {
    const searchQuery = this.searchQuery().toLowerCase();
    const selectedCategory = this.selectedCategory();
    const selectedLocation = this.selectedLocation();
    const selectedUrgency = this.selectedUrgency();

    const filtered = this.allRequests().filter((request) => {
      const matchesSearch =
        request.title.toLowerCase().includes(searchQuery) ||
        request.organization.toLowerCase().includes(searchQuery);
      const matchesCategory = !selectedCategory || request.category === selectedCategory;
      const matchesLocation = !selectedLocation || request.location === selectedLocation;
      const matchesUrgency =
        !selectedUrgency || this.getUrgencyLabel(request.urgency) === selectedUrgency;

      return matchesSearch && matchesCategory && matchesLocation && matchesUrgency;
    });

    switch (this.sortBy()) {
      case 'most-funded':
        return [...filtered].sort((a, b) => {
          const progressA = (a.progress / a.target) * 100;
          const progressB = (b.progress / b.target) * 100;
          return progressB - progressA;
        });
      case 'most-urgent':
        return [...filtered].sort((a, b) => {
          const urgencyOrder = { high: 0, medium: 1, low: 2 };
          return urgencyOrder[a.urgency] - urgencyOrder[b.urgency];
        });
      default:
        return filtered;
    }
  });

  constructor() {
    this.isAssociation.set(this.auth.getRole() === 'association');

    if (!this.isAssociation()) {
      this.router.navigateByUrl('/explorer');
    }
  }

  getUrgencyLabel(urgency: 'low' | 'medium' | 'high'): string {
    switch (urgency) {
      case 'high':
        return 'Haute';
      case 'medium':
        return 'Moyenne';
      default:
        return 'Basse';
    }
  }

  getProgressPercent(progress: number, target: number): number {
    return (progress / target) * 100;
  }

  clearFilters() {
    this.searchQuery.set('');
    this.selectedCategory.set('');
    this.selectedLocation.set('');
    this.selectedUrgency.set('');
    this.sortBy.set('recent');
  }

  openRequest(requestId: number) {
    this.router.navigate(['/request-detail', requestId]);
  }

  collaborate(request: RequestCard) {
    this.router.navigate(['/request-detail', request.id]);
  }

  supportRequest(request: RequestCard) {
    this.router.navigate(['/request-detail', request.id]);
  }

  takeOwnership(request: RequestCard) {
    this.router.navigate(['/request-detail', request.id]);
  }

  donateToRequest(request: RequestCard) {
    this.router.navigate(['/request-detail', request.id]);
  }

  contactRequester(request: RequestCard) {
    const subject = encodeURIComponent(`Demande ${request.title}`);
    window.location.href = `mailto:support@sanad.tn?subject=${subject}`;
  }

  createCampaignFromRequest(request: RequestCard) {
    this.router.navigate(['/association/campaigns/new'], {
      queryParams: { parentRequestId: request.id }
    });
  }
}
